import json

DATA = "/root/autodl-tmp/trace-verdict-study-data/exception_only_test.jsonl"
test = []
with open(DATA) as f:
    for line in f:
        test.append(json.loads(line))

# MBPP/113: check which samples are identical
print("MBPP/113 input uniqueness:")
inputs = {}
for i in range(540, 550):
    inp = test[i]['input']
    h = hash(inp)
    if h not in inputs:
        inputs[h] = []
    inputs[h].append(i)

for h, ids in inputs.items():
    print(f"  Group ({len(ids)} samples): {ids}")
    inp = test[ids[0]]['input']
    if 'Execution trace:' in inp:
        trace = inp[inp.index('Execution trace:'):]
        print(f"    Trace: {trace[:150]}")

# HumanEval/95: check uniqueness
print("\nHumanEval/95 input uniqueness:")
inputs95 = {}
for i in range(900, 910):
    inp = test[i]['input']
    h = hash(inp)
    if h not in inputs95:
        inputs95[h] = []
    inputs95[h].append(i)

for h, ids in inputs95.items():
    print(f"  Group ({len(ids)} samples): {ids}, label={test[ids[0]]['output']}")

