import os
BASE = "/root/autodl-tmp/trace-verdict-study-checkpoints"
pds = {}
with open(f"{BASE}/deepseek_exception_only/final/predictions.jsonl") as f:
    for line in f:
        d = json.loads(line)
        pds[d['id']] = d

print("\nDeepSeek on MBPP/113 (all 10 samples):")
for i in range(540, 550):
    print(f"  ID={i}: label={test[i]['output']}, DS_pred={pds[i]['pred']}, raw={pds[i]['raw_pred']}")

# Count total duplicate samples in test set
print("\nDuplicate analysis (full test set):")
all_inputs = {}
for i, d in enumerate(test):
    h = hash(d['input'])
    if h not in all_inputs:
        all_inputs[h] = []
    all_inputs[h].append(i)

dups = {h: ids for h, ids in all_inputs.items() if len(ids) > 1}
print(f"  Total unique inputs: {len(all_inputs)}")
print(f"  Inputs with duplicates: {len(dups)}")
dup_count = sum(len(ids) for ids in dups.values())
print(f"  Total samples that are duplicates: {dup_count}")

# How many of the duplicates involve error samples?
error_ids = {540, 541, 542, 543, 548, 549, 901, 905}
for h, ids in dups.items():
    if any(i in error_ids for i in ids):
        pid = test[ids[0]]['problem_id']
        label = test[ids[0]]['output']
        print(f"  Dup group with errors: IDs={ids}, problem={pid}, label={label}")

